#include <vector>
#include <string>
#include <algorithm>

class Solution {
private:
    bool isPalindrome(long long x) {
        if (x < 0) return false;
        std::string s = std::to_string(x);
        int l = 0, r = (int)s.size() - 1;
        while (l < r) {
            if (s[l++] != s[r--]) return false;
        }
        return true;
    }
public:
    int countPalindromicSubarraySums(std::vector<int>& nums) {
        int n = nums.size();
        int ans = 0;
        for (int i = 0; i < n; ++i) {
            long long cur = 0;
            for (int j = i; j < n; ++j) {
                cur += nums[j];
                if (cur >= 0 && isPalindrome(cur)) ans++;
            }
        }
        return ans;
    }
};

class Solution {
    private boolean isPalindrome(long x) {
        if (x < 0) return false;
        String s = Long.toString(x);
        int l = 0, r = s.length() - 1;
        while (l < r) {
            if (s.charAt(l++) != s.charAt(r--)) return false;
        }
        return true;
    }

    public int countPalindromicSubarraySums(int[] nums) {
        int n = nums.length;
        int ans = 0;
        for (int i = 0; i < n; i++) {
            long cur = 0;
            for (int j = i; j < n; j++) {
                cur += nums[j];
                if (cur >= 0 && isPalindrome(cur)) ans++;
            }
        }
        return ans;
    }
}

